(function(root){
 const copy=x=>JSON.parse(JSON.stringify(x));
 function text(v,max,name){const s=String(v||'').trim();if(!s||s.length>max)throw Error(`${name}需填写 1–${max} 个字`);return s}
 function post(raw,id,at){return {id,title:text(raw.title,80,'标题'),content:text(raw.content,3000,'帖子'),board:['日常','树洞','脑洞'].includes(raw.board)?raw.board:'日常',author:raw.author||'me',name:String(raw.name||'我').slice(0,40),anonymous:!!raw.anonymous,aliases:raw.anonymous?{[raw.author||'me']:'匿名花瓣 01'}:{},comments:[],liked:false,at}}
 function label(p,item){return item.anonymous?p.aliases[item.author]||'匿名花瓣':item.name||'访客'}
 function alias(p,actor){if(p.aliases[actor])return p.aliases[actor];let n=1;while(Object.values(p.aliases).includes('匿名花瓣 '+String(n).padStart(2,'0')))n++;return '匿名花瓣 '+String(n).padStart(2,'0')}
 function comment(original,raw,id,at){const p=copy(original);if(p.comments.length>=200)throw Error('每帖最多 200 条回复');const parent=raw.parentId?p.comments.find(c=>c.id===raw.parentId):null;if(raw.parentId&&!parent)throw Error('要回复的评论不存在');const c={id,author:raw.author||'me',name:String(raw.name||'我').slice(0,40),anonymous:!!raw.anonymous,parentId:parent?.id||'',content:text(raw.content,1500,'回复'),at};if(c.anonymous&&!p.aliases[c.author])p.aliases[c.author]=alias(p,c.author);p.comments.push(c);return p}
 function publicThread(p){return {标题:p.title,分区:p.board,作者:label(p,p),正文:p.content,讨论:p.comments.slice(-30).map(c=>({序号:c.id,显示名:label(p,c),回复谁:c.parentId?label(p,p.comments.find(x=>x.id===c.parentId)||{}):'',内容:c.content}))}}
 function parseJSON(value){const s=String(value).trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{return JSON.parse(s)}catch{throw Error('模型未返回有效 JSON，请重试或更换模型')}}
 function discussion(value,actors,p){const data=parseJSON(value);if(!Array.isArray(data.replies)||!data.replies.length||data.replies.length>4)throw Error('讨论应包含 1–4 条回复');return data.replies.map(r=>{if(!actors.some(a=>a.id===r.speaker))throw Error('模型使用了未选择的发言者');if(r.parentId&&!p.comments.some(c=>c.id===r.parentId))throw Error('模型回复了不存在的评论');return {author:r.speaker,parentId:r.parentId||'',content:text(r.content,1500,'讨论')}})}
 function world(raw,id,at){const seen=new Set(),cast=(raw.cast||[]).filter(x=>{if(seen.has(x.id))return false;seen.add(x.id);return true}).map(x=>({id:x.id,name:text(x.name,40,'角色名字'),persona:text(x.persona||'自然回应剧情',5000,'角色设定'),identity:String(x.identity||'遵循世界观融入身份').slice(0,300)}));if(!cast.length||cast.length>4)throw Error('请选择 1–4 位角色');return {id,title:text(raw.title,60,'世界名称'),setting:text(raw.setting,6000,'世界观'),rules:String(raw.rules||'').trim().slice(0,3000),player:text(raw.player||'以自己的身份探索世界',1000,'玩家身份'),opening:text(raw.opening,1500,'开场'),cast,messages:[],memory:{summary:'',covered:0},pinned:'',turn:0,pending:false,at,updatedAt:at}}
 function scene(value,w){const d=parseJSON(value);if(!Array.isArray(d.messages)||!d.messages.length||d.messages.length>6)throw Error('每轮需返回 1–6 段剧情');return d.messages.map(m=>{if(m.speaker!=='narrator'&&!w.cast.some(c=>c.id===m.speaker))throw Error('剧情出现了未加入的角色');return {speaker:m.speaker,content:text(m.content,2000,'剧情内容')}})}
 function action(w,value,id,at){if(w.pending)throw Error('先重试或取消上一轮');if(w.messages.length>=1000)throw Error('存档已满，请导出后创建新世界');const n=copy(w);n.messages.push({id,speaker:'player',content:text(value,1500,'行动'),at});n.pending=true;n.updatedAt=at;return n}
 function finish(w,messages,id,at){if(!w.pending)throw Error('这一轮已结束');const n=copy(w);n.messages.push(...messages.map((m,i)=>({...m,id:id(i),at})));n.pending=false;n.turn++;n.updatedAt=at;return n}
 function simulatorContext(w){return {世界名称:w.title,世界观:w.setting,规则:w.rules,玩家身份:w.player,开场:w.opening,参演角色:w.cast,固定剧情记忆:w.pinned,已发生剧情摘要:w.memory.summary,最近剧情:w.messages.slice(-24).map(m=>({发言者:m.speaker,内容:m.content}))}}
 const api={copy,text,post,label,comment,publicThread,parseJSON,discussion,world,scene,action,finish,simulatorContext};root.PalaisStudio=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
